WITH authored AS (SELECT value AS doc FROM jsonb_array_elements($authored$[{"case_key":"budget-region-2026-40-industrial-grid","title":"Промышленная площадка и подключение к сетям","status":"ready","situation":"В учебном сценарии Калужской области восемь новых предприятий работают на промышленной площадке с временным электроснабжением. Эти восемь предприятий ещё не включены в сохранённую начальную базу. Ещё двадцать участков нельзя подключить к постоянным сетям. Регион просит финансирование подъездной дороги, инженерной инфраструктуры и проверки готовности подключения. Общая смета — 1000 млн ₽; федеральная заявка — 800 млн ₽. Регион заявляет 200 млн ₽ собственных средств. Заявка рассматривается в расходах проекта федерального бюджета; подача заявки не означает выделение или перечисление средств.\n\nУправленческая постановка. Вопрос «промышленная площадка и подключение к сетям» включён в повестку бюджетной команды до окончательного согласования соответствующей финансовой операции. Из представленных сведений следует, что первоначальная потребность или обязательство существуют независимо от формы будущего решения. Требуется оценить не только предпочтительный источник средств, но и допустимость его использования именно на текущем этапе. Участники обязаны различать прогноз поступления, принятые лимиты, проект решения и уже состоявшийся платёж. Даже экономически целесообразный вариант не становится исполнимым лишь после одобрения в рабочем чате.\n\nРазграничение полномочий. К вопросу относятся министр финансов, председатель правительства, губернатор, глава региона, министр экономики. Представление расчёта, отраслевое согласование, установление расходного обязательства и организация казначейского исполнения представляют собой разные административные действия. Один участник вправе инициировать проверку, другой — подтвердить показатели, третий — подписать документ в пределах своей компетенции. При недостаточности полномочий требуется формальное обращение к уполномоченному органу; последующая подпись не всегда устраняет последствия преждевременно исполненной операции.\n\nПроверка исходных данных. Для решения следует сопоставить первоначальную справку с подтверждающими материалами, установить расчётный период, получателя средств, правовое основание и ответственного за исполнение. В описанном случае предмет проверки касается запрашиваемых бюджетных расходов и межбюджетного финансирования. Если используются прогнозные показатели, они должны сохранять статус прогноза до появления надлежащего подтверждения. При возвратных операциях отдельно учитываются сумма основного обязательства, проценты и срок платежа; при трансфертах — форма, целевое назначение и условия софинансирования.\n\nРесурсные и временные ограничения. Финансовый орган не может считать будущие средства уже доступными, а ведомство-инициатор не должно обещать результат, выполнение которого зависит от неподтверждённых решений других участников. Полная повторная экспертиза может защитить от ошибки в расчётах, но при этом затянуть решение обозначенной проблемы. Срочное финансирование, напротив, способно временно улучшить показатель, однако без проверки процедуры оставит риск возврата средств или невозможности исполнения. Важно выбрать последовательность мероприятий, для которой можно установить проверяемые контрольные точки.\n\nИнтересы и публичная отчётность. Для получателей услуги и жителей важна предсказуемость сроков; для профильной организации — непрерывность деятельности; для контрольного органа — прозрачность оснований; для бюджетной команды — сопоставимость показателей по всем уровням финансового плана. Некоторые профессионально сформулированные способы действий будут юридически допустимыми только после дополнительных условий, хотя в текущей ситуации уступят другому варианту по срокам или ресурсам. Прежде чем проголосовать, определите, какой из пяти вариантов сразу запускает наиболее обоснованную цепочку действий, не подменяя решение обещанием последующего оформления. Письменное обоснование не требуется.","decision_options":["Уточнить мощность и очерёдность подключения перед направлением заявки","Учесть восемь действующих предприятий и подготовить заявку по техническим условиям","Предусмотреть поэтапную региональную поддержку только по бесспорно подтверждённой части потребности и отдельно продолжить федеральное согласование","Разделить расходы между краткосрочным мероприятием и инвестиционной программой, утвердив окончательный объём после повторного отраслевого расчёта","Согласовать предварительное распределение на основании проекта региональной заявки, предполагая последующее оформление федерального источника"],"effect_plan":{"options":[{"key":"option_1","news":"Подготовка итогового решения перенесена до дополнительной сверки.","trust":0,"lawful":true,"description":"Выбран дополнительный контрольный этап. Его проведение допустимо, но отодвигает решение основной задачи, описанной в обстоятельствах события.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":0.002,"enterprises":5},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false},{"key":"option_2","news":"Промышленная площадка и подключение к сетям — Заявка подготовлена","trust":2,"lawful":true,"description":"В базе отражены восемь уже действующих предприятий. Заявка на сети подготовлена; двадцать неподключённых участков не считаются новыми предприятиями и не создают текущего дохода.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"activity":0.004,"enterprises":8},"public_interest":"beneficial","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":true},{"key":"option_3","news":"Региональные и федеральные меры разделены, результат остаётся неполным.","trust":0,"lawful":true,"description":"Частичный способ финансирования может быть законным при самостоятельном подтверждении лимитов, однако не обеспечивает комплексного решения в рамках текущей заявки.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":0.002,"enterprises":5},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false},{"key":"option_4","news":"Исполнение разделено на этапы, вопрос сроков остался открытым.","trust":-1,"lawful":true,"description":"Поэтапное изменение возможно в установленной процедуре, но выбранная последовательность не отвечает основному срочному ограничению и требует отдельного решения.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":0.002,"enterprises":5},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false},{"key":"option_5","news":"Контролёры обнаружили несоответствие последовательности финансовых решений.","trust":-2,"lawful":false,"description":"Предварительная договорённость не заменяет документального основания бюджетного обязательства. Последующее оформление не устраняет исходную процедурную ошибку.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы и результаты должны опираться на подтверждённые расчёты. Фиктивный учёт средств, работ или результатов нарушает учебную процедуру. Вариант размечен автором как недопустимый в игре; это не заключение о действующих нормах права.","fiscal_effect":{"cost":0.004,"activity":-0.009,"enterprises":4},"public_interest":"harmful","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false}]},"allowed_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"comic_scene":{"scene_id":"scene-budget-region-2026-40-industrial-grid","case_key":"budget-region-2026-40-industrial-grid","title":"Промышленная площадка и подключение к сетям","category":"Региональные финансы","format":"animated-svg","version":1,"alt":"Авторская сцена к ситуации «Промышленная площадка и подключение к сетям»","media_label":"Региональный финансовый обзор","news_lead":"Бюджетная комиссия обсуждает ситуацию «Промышленная площадка и подключение к сетям»."},"source_note":"Авторская учебная ситуация GOS//SIMS, не сообщение о реальном происшествии. Все суммы, сметы, исходные показатели и последствия являются параметрами игры, а не официальной статистикой. География соответствует справочнику проекта. Бюджетный маршрут основан на правилах игры, этап 13; действующие нормы права здесь не пересказываются."},{"case_key":"budget-region-2026-42-employment-retraining","title":"Спад заказов и переобучение работников","status":"ready","situation":"В учебном сценарии Кемеровской области — Кузбасса спад заказов оставил 1 200 работников без устойчивой занятости; десять небольших предприятий приостановили работу. Регион подготовил программу переобучения и трудоустройства для 700 участников с проверкой договорённостей с работодателями. Общая смета — 600 млн ₽; федеральная заявка — 480 млн ₽. Регион заявляет 120 млн ₽ собственных средств. Заявка рассматривается в расходах проекта федерального бюджета; подача заявки не означает выделение или перечисление средств.\n\nУправленческая постановка. Вопрос «спад заказов и переобучение работников» включён в повестку бюджетной команды до окончательного согласования соответствующей финансовой операции. Из представленных сведений следует, что первоначальная потребность или обязательство существуют независимо от формы будущего решения. Требуется оценить не только предпочтительный источник средств, но и допустимость его использования именно на текущем этапе. Участники обязаны различать прогноз поступления, принятые лимиты, проект решения и уже состоявшийся платёж. Даже экономически целесообразный вариант не становится исполнимым лишь после одобрения в рабочем чате.\n\nРазграничение полномочий. К вопросу относятся министр финансов, председатель правительства, губернатор, глава региона, министр труда. Представление расчёта, отраслевое согласование, установление расходного обязательства и организация казначейского исполнения представляют собой разные административные действия. Один участник вправе инициировать проверку, другой — подтвердить показатели, третий — подписать документ в пределах своей компетенции. При недостаточности полномочий требуется формальное обращение к уполномоченному органу; последующая подпись не всегда устраняет последствия преждевременно исполненной операции.\n\nПроверка исходных данных. Для решения следует сопоставить первоначальную справку с подтверждающими материалами, установить расчётный период, получателя средств, правовое основание и ответственного за исполнение. В описанном случае предмет проверки касается запрашиваемых бюджетных расходов и межбюджетного финансирования. Если используются прогнозные показатели, они должны сохранять статус прогноза до появления надлежащего подтверждения. При возвратных операциях отдельно учитываются сумма основного обязательства, проценты и срок платежа; при трансфертах — форма, целевое назначение и условия софинансирования.\n\nРесурсные и временные ограничения. Финансовый орган не может считать будущие средства уже доступными, а ведомство-инициатор не должно обещать результат, выполнение которого зависит от неподтверждённых решений других участников. Полная повторная экспертиза может защитить от ошибки в расчётах, но при этом затянуть решение обозначенной проблемы. Срочное финансирование, напротив, способно временно улучшить показатель, однако без проверки процедуры оставит риск возврата средств или невозможности исполнения. Важно выбрать последовательность мероприятий, для которой можно установить проверяемые контрольные точки.\n\nИнтересы и публичная отчётность. Для получателей услуги и жителей важна предсказуемость сроков; для профильной организации — непрерывность деятельности; для контрольного органа — прозрачность оснований; для бюджетной команды — сопоставимость показателей по всем уровням финансового плана. Некоторые профессионально сформулированные способы действий будут юридически допустимыми только после дополнительных условий, хотя в текущей ситуации уступят другому варианту по срокам или ресурсам. Прежде чем проголосовать, определите, какой из пяти вариантов сразу запускает наиболее обоснованную цепочку действий, не подменяя решение обещанием последующего оформления. Письменное обоснование не требуется.","decision_options":["Проверить спрос на профессии и скорректировать заявку после переговоров","Подготовить заявку с реестром участников и подтверждёнными вакансиями","Предусмотреть поэтапную региональную поддержку только по бесспорно подтверждённой части потребности и отдельно продолжить федеральное согласование","Разделить расходы между краткосрочным мероприятием и инвестиционной программой, утвердив окончательный объём после повторного отраслевого расчёта","Согласовать предварительное распределение на основании проекта региональной заявки, предполагая последующее оформление федерального источника"],"effect_plan":{"options":[{"key":"option_1","news":"Подготовка итогового решения перенесена до дополнительной сверки.","trust":0,"lawful":true,"description":"Выбран дополнительный контрольный этап. Его проведение допустимо, но отодвигает решение основной задачи, описанной в обстоятельствах события.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.006,"activity":-0.023,"enterprises":-20},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр труда"],"protects_role_interest":false},{"key":"option_2","news":"Спад заказов и переобучение работников — Заявка подготовлена","trust":2,"lawful":true,"description":"Заявка связывает обучение с вакансиями. Уже произошедший спад уменьшает число действующих предприятий и активность; будущие рабочие места не зачисляются до исполнения программы.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.004,"activity":-0.015,"enterprises":-10},"public_interest":"beneficial","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр труда"],"protects_role_interest":true},{"key":"option_3","news":"Региональные и федеральные меры разделены, результат остаётся неполным.","trust":0,"lawful":true,"description":"Частичный способ финансирования может быть законным при самостоятельном подтверждении лимитов, однако не обеспечивает комплексного решения в рамках текущей заявки.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.006,"activity":-0.023,"enterprises":-20},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр труда"],"protects_role_interest":false},{"key":"option_4","news":"Исполнение разделено на этапы, вопрос сроков остался открытым.","trust":-1,"lawful":true,"description":"Поэтапное изменение возможно в установленной процедуре, но выбранная последовательность не отвечает основному срочному ограничению и требует отдельного решения.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.006,"activity":-0.023,"enterprises":-20},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр труда"],"protects_role_interest":false},{"key":"option_5","news":"Контролёры обнаружили несоответствие последовательности финансовых решений.","trust":-2,"lawful":false,"description":"Предварительная договорённость не заменяет документального основания бюджетного обязательства. Последующее оформление не устраняет исходную процедурную ошибку.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы и результаты должны опираться на подтверждённые расчёты. Фиктивный учёт средств, работ или результатов нарушает учебную процедуру. Вариант размечен автором как недопустимый в игре; это не заключение о действующих нормах права.","fiscal_effect":{"cost":0.01,"activity":-0.035,"enterprises":-35},"public_interest":"harmful","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр труда"],"protects_role_interest":false}]},"allowed_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр труда"],"comic_scene":{"scene_id":"scene-budget-region-2026-42-employment-retraining","case_key":"budget-region-2026-42-employment-retraining","title":"Спад заказов и переобучение работников","category":"Региональные финансы","format":"animated-svg","version":1,"alt":"Авторская сцена к ситуации «Спад заказов и переобучение работников»","media_label":"Региональный финансовый обзор","news_lead":"Бюджетная комиссия обсуждает ситуацию «Спад заказов и переобучение работников»."},"source_note":"Авторская учебная ситуация GOS//SIMS, не сообщение о реальном происшествии. Все суммы, сметы, исходные показатели и последствия являются параметрами игры, а не официальной статистикой. География соответствует справочнику проекта. Бюджетный маршрут основан на правилах игры, этап 13; действующие нормы права здесь не пересказываются."},{"case_key":"budget-region-2026-43-rural-cultural-centres","title":"Сельские культурные центры после обследования","status":"ready","situation":"В учебном сценарии Кировской области пять сельских культурных центров ограничили работу из-за состояния помещений и оборудования. Регион представил проект ремонта, доступности для маломобильных посетителей и обновления оборудования; каждому объекту соответствует дефектная ведомость. Общая смета — 200 млн ₽; федеральная заявка — 160 млн ₽. Регион заявляет 40 млн ₽ собственных средств. Заявка рассматривается в расходах проекта федерального бюджета; подача заявки не означает выделение или перечисление средств.\n\nУправленческая постановка. Вопрос «сельские культурные центры после обследования» включён в повестку бюджетной команды до окончательного согласования соответствующей финансовой операции. Из представленных сведений следует, что первоначальная потребность или обязательство существуют независимо от формы будущего решения. Требуется оценить не только предпочтительный источник средств, но и допустимость его использования именно на текущем этапе. Участники обязаны различать прогноз поступления, принятые лимиты, проект решения и уже состоявшийся платёж. Даже экономически целесообразный вариант не становится исполнимым лишь после одобрения в рабочем чате.\n\nРазграничение полномочий. К вопросу относятся министр финансов, председатель правительства, губернатор, глава региона, министр культуры. Представление расчёта, отраслевое согласование, установление расходного обязательства и организация казначейского исполнения представляют собой разные административные действия. Один участник вправе инициировать проверку, другой — подтвердить показатели, третий — подписать документ в пределах своей компетенции. При недостаточности полномочий требуется формальное обращение к уполномоченному органу; последующая подпись не всегда устраняет последствия преждевременно исполненной операции.\n\nПроверка исходных данных. Для решения следует сопоставить первоначальную справку с подтверждающими материалами, установить расчётный период, получателя средств, правовое основание и ответственного за исполнение. В описанном случае предмет проверки касается запрашиваемых бюджетных расходов и межбюджетного финансирования. Если используются прогнозные показатели, они должны сохранять статус прогноза до появления надлежащего подтверждения. При возвратных операциях отдельно учитываются сумма основного обязательства, проценты и срок платежа; при трансфертах — форма, целевое назначение и условия софинансирования.\n\nРесурсные и временные ограничения. Финансовый орган не может считать будущие средства уже доступными, а ведомство-инициатор не должно обещать результат, выполнение которого зависит от неподтверждённых решений других участников. Полная повторная экспертиза может защитить от ошибки в расчётах, но при этом затянуть решение обозначенной проблемы. Срочное финансирование, напротив, способно временно улучшить показатель, однако без проверки процедуры оставит риск возврата средств или невозможности исполнения. Важно выбрать последовательность мероприятий, для которой можно установить проверяемые контрольные точки.\n\nИнтересы и публичная отчётность. Для получателей услуги и жителей важна предсказуемость сроков; для профильной организации — непрерывность деятельности; для контрольного органа — прозрачность оснований; для бюджетной команды — сопоставимость показателей по всем уровням финансового плана. Некоторые профессионально сформулированные способы действий будут юридически допустимыми только после дополнительных условий, хотя в текущей ситуации уступят другому варианту по срокам или ресурсам. Прежде чем проголосовать, определите, какой из пяти вариантов сразу запускает наиболее обоснованную цепочку действий, не подменяя решение обещанием последующего оформления. Письменное обоснование не требуется.","decision_options":["Подготовить заявку по объектам и сохранить доступные временные услуги","Уточнить перечень услуг и состояние каждого объекта","Предусмотреть поэтапную региональную поддержку только по бесспорно подтверждённой части потребности и отдельно продолжить федеральное согласование","Разделить расходы между краткосрочным мероприятием и инвестиционной программой, утвердив окончательный объём после повторного отраслевого расчёта","Согласовать предварительное распределение на основании проекта региональной заявки, предполагая последующее оформление федерального источника"],"effect_plan":{"options":[{"key":"option_1","news":"Сельские культурные центры после обследования — Заявка подготовлена","trust":2,"lawful":true,"description":"Объекты и затраты включены в заявку, временные услуги раскрыты жителям. Ограничения пока снижают местную активность; ремонт не считается выполненным заранее.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.001,"activity":-0.002},"public_interest":"beneficial","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр культуры"],"protects_role_interest":true},{"key":"option_2","news":"Подготовка итогового решения перенесена до дополнительной сверки.","trust":0,"lawful":true,"description":"Выбран дополнительный контрольный этап. Его проведение допустимо, но отодвигает решение основной задачи, описанной в обстоятельствах события.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.004},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр культуры"],"protects_role_interest":false},{"key":"option_3","news":"Региональные и федеральные меры разделены, результат остаётся неполным.","trust":0,"lawful":true,"description":"Частичный способ финансирования может быть законным при самостоятельном подтверждении лимитов, однако не обеспечивает комплексного решения в рамках текущей заявки.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.004},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр культуры"],"protects_role_interest":false},{"key":"option_4","news":"Исполнение разделено на этапы, вопрос сроков остался открытым.","trust":-1,"lawful":true,"description":"Поэтапное изменение возможно в установленной процедуре, но выбранная последовательность не отвечает основному срочному ограничению и требует отдельного решения.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.004},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр культуры"],"protects_role_interest":false},{"key":"option_5","news":"Контролёры обнаружили несоответствие последовательности финансовых решений.","trust":-2,"lawful":false,"description":"Предварительная договорённость не заменяет документального основания бюджетного обязательства. Последующее оформление не устраняет исходную процедурную ошибку.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы и результаты должны опираться на подтверждённые расчёты. Фиктивный учёт средств, работ или результатов нарушает учебную процедуру. Вариант размечен автором как недопустимый в игре; это не заключение о действующих нормах права.","fiscal_effect":{"cost":0.004,"activity":-0.007},"public_interest":"harmful","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр культуры"],"protects_role_interest":false}]},"allowed_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр культуры"],"comic_scene":{"scene_id":"scene-budget-region-2026-43-rural-cultural-centres","case_key":"budget-region-2026-43-rural-cultural-centres","title":"Сельские культурные центры после обследования","category":"Региональные финансы","format":"animated-svg","version":1,"alt":"Авторская сцена к ситуации «Сельские культурные центры после обследования»","media_label":"Региональный финансовый обзор","news_lead":"Бюджетная комиссия обсуждает ситуацию «Сельские культурные центры после обследования»."},"source_note":"Авторская учебная ситуация GOS//SIMS, не сообщение о реальном происшествии. Все суммы, сметы, исходные показатели и последствия являются параметрами игры, а не официальной статистикой. География соответствует справочнику проекта. Бюджетный маршрут основан на правилах игры, этап 13; действующие нормы права здесь не пересказываются."},{"case_key":"budget-region-2026-45-rural-broadband","title":"Связь для удалённых поселений","status":"ready","situation":"В учебном сценарии Курганской области восемнадцать населённых пунктов не имеют устойчивого широкополосного доступа. Местные предприниматели не могут регулярно передавать заказы, а социальные учреждения используют нестабильные каналы. Регион подготовил трассировку сети и список точек подключения. Общая смета — 450 млн ₽; федеральная заявка — 360 млн ₽. Регион заявляет 90 млн ₽ собственных средств. Заявка рассматривается в расходах проекта федерального бюджета; подача заявки не означает выделение или перечисление средств.\n\nУправленческая постановка. Вопрос «связь для удалённых поселений» включён в повестку бюджетной команды до окончательного согласования соответствующей финансовой операции. Из представленных сведений следует, что первоначальная потребность или обязательство существуют независимо от формы будущего решения. Требуется оценить не только предпочтительный источник средств, но и допустимость его использования именно на текущем этапе. Участники обязаны различать прогноз поступления, принятые лимиты, проект решения и уже состоявшийся платёж. Даже экономически целесообразный вариант не становится исполнимым лишь после одобрения в рабочем чате.\n\nРазграничение полномочий. К вопросу относятся министр финансов, председатель правительства, губернатор, глава региона, министр цифрового развития. Представление расчёта, отраслевое согласование, установление расходного обязательства и организация казначейского исполнения представляют собой разные административные действия. Один участник вправе инициировать проверку, другой — подтвердить показатели, третий — подписать документ в пределах своей компетенции. При недостаточности полномочий требуется формальное обращение к уполномоченному органу; последующая подпись не всегда устраняет последствия преждевременно исполненной операции.\n\nПроверка исходных данных. Для решения следует сопоставить первоначальную справку с подтверждающими материалами, установить расчётный период, получателя средств, правовое основание и ответственного за исполнение. В описанном случае предмет проверки касается запрашиваемых бюджетных расходов и межбюджетного финансирования. Если используются прогнозные показатели, они должны сохранять статус прогноза до появления надлежащего подтверждения. При возвратных операциях отдельно учитываются сумма основного обязательства, проценты и срок платежа; при трансфертах — форма, целевое назначение и условия софинансирования.\n\nРесурсные и временные ограничения. Финансовый орган не может считать будущие средства уже доступными, а ведомство-инициатор не должно обещать результат, выполнение которого зависит от неподтверждённых решений других участников. Полная повторная экспертиза может защитить от ошибки в расчётах, но при этом затянуть решение обозначенной проблемы. Срочное финансирование, напротив, способно временно улучшить показатель, однако без проверки процедуры оставит риск возврата средств или невозможности исполнения. Важно выбрать последовательность мероприятий, для которой можно установить проверяемые контрольные точки.\n\nИнтересы и публичная отчётность. Для получателей услуги и жителей важна предсказуемость сроков; для профильной организации — непрерывность деятельности; для контрольного органа — прозрачность оснований; для бюджетной команды — сопоставимость показателей по всем уровням финансового плана. Некоторые профессионально сформулированные способы действий будут юридически допустимыми только после дополнительных условий, хотя в текущей ситуации уступят другому варианту по срокам или ресурсам. Прежде чем проголосовать, определите, какой из пяти вариантов сразу запускает наиболее обоснованную цепочку действий, не подменяя решение обещанием последующего оформления. Письменное обоснование не требуется.","decision_options":["Проверить альтернативные технологии и уточнить смету","Предусмотреть поэтапную региональную поддержку только по бесспорно подтверждённой части потребности и отдельно продолжить федеральное согласование","Разделить расходы между краткосрочным мероприятием и инвестиционной программой, утвердив окончательный объём после повторного отраслевого расчёта","Согласовать предварительное распределение на основании проекта региональной заявки, предполагая последующее оформление федерального источника","Подготовить заявку по трассировке и проверяемым точкам подключения"],"effect_plan":{"options":[{"key":"option_1","news":"Подготовка итогового решения перенесена до дополнительной сверки.","trust":0,"lawful":true,"description":"Выбран дополнительный контрольный этап. Его проведение допустимо, но отодвигает решение основной задачи, описанной в обстоятельствах события.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.006},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр цифрового развития"],"protects_role_interest":false},{"key":"option_2","news":"Региональные и федеральные меры разделены, результат остаётся неполным.","trust":0,"lawful":true,"description":"Частичный способ финансирования может быть законным при самостоятельном подтверждении лимитов, однако не обеспечивает комплексного решения в рамках текущей заявки.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.006},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр цифрового развития"],"protects_role_interest":false},{"key":"option_3","news":"Исполнение разделено на этапы, вопрос сроков остался открытым.","trust":-1,"lawful":true,"description":"Поэтапное изменение возможно в установленной процедуре, но выбранная последовательность не отвечает основному срочному ограничению и требует отдельного решения.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.006},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр цифрового развития"],"protects_role_interest":false},{"key":"option_4","news":"Контролёры обнаружили несоответствие последовательности финансовых решений.","trust":-2,"lawful":false,"description":"Предварительная договорённость не заменяет документального основания бюджетного обязательства. Последующее оформление не устраняет исходную процедурную ошибку.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы и результаты должны опираться на подтверждённые расчёты. Фиктивный учёт средств, работ или результатов нарушает учебную процедуру. Вариант размечен автором как недопустимый в игре; это не заключение о действующих нормах права.","fiscal_effect":{"cost":0.004,"activity":-0.01},"public_interest":"harmful","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр цифрового развития"],"protects_role_interest":false},{"key":"option_5","news":"Связь для удалённых поселений — Заявка подготовлена","trust":2,"lawful":true,"description":"Список точек и расчёт сети приложены к заявке. Текущие ограничения связи продолжают сдерживать заказы; доступ не считается предоставленным по одному обещанию.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"activity":-0.002},"public_interest":"beneficial","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр цифрового развития"],"protects_role_interest":true}]},"allowed_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр цифрового развития"],"comic_scene":{"scene_id":"scene-budget-region-2026-45-rural-broadband","case_key":"budget-region-2026-45-rural-broadband","title":"Связь для удалённых поселений","category":"Региональные финансы","format":"animated-svg","version":1,"alt":"Авторская сцена к ситуации «Связь для удалённых поселений»","media_label":"Региональный финансовый обзор","news_lead":"Бюджетная комиссия обсуждает ситуацию «Связь для удалённых поселений»."},"source_note":"Авторская учебная ситуация GOS//SIMS, не сообщение о реальном происшествии. Все суммы, сметы, исходные показатели и последствия являются параметрами игры, а не официальной статистикой. География соответствует справочнику проекта. Бюджетный маршрут основан на правилах игры, этап 13; действующие нормы права здесь не пересказываются."},{"case_key":"budget-region-2026-47-food-logistics","title":"Складская сеть для местных производителей","status":"ready","situation":"В учебном сценарии Ленинградской области десять небольших производителей уже начали работу, но из-за нехватки холодного хранения теряют 22% скоропортящейся продукции. Регион предлагает создать общий логистический узел, подъезд и систему учёта поставок. Эти десять производителей ещё не включены в сохранённую начальную базу; склад ещё не построен. Общая смета — 700 млн ₽; федеральная заявка — 560 млн ₽. Регион заявляет 140 млн ₽ собственных средств. Заявка рассматривается в расходах проекта федерального бюджета; подача заявки не означает выделение или перечисление средств.\n\nУправленческая постановка. Вопрос «складская сеть для местных производителей» включён в повестку бюджетной команды до окончательного согласования соответствующей финансовой операции. Из представленных сведений следует, что первоначальная потребность или обязательство существуют независимо от формы будущего решения. Требуется оценить не только предпочтительный источник средств, но и допустимость его использования именно на текущем этапе. Участники обязаны различать прогноз поступления, принятые лимиты, проект решения и уже состоявшийся платёж. Даже экономически целесообразный вариант не становится исполнимым лишь после одобрения в рабочем чате.\n\nРазграничение полномочий. К вопросу относятся министр финансов, председатель правительства, губернатор, глава региона, министр экономики. Представление расчёта, отраслевое согласование, установление расходного обязательства и организация казначейского исполнения представляют собой разные административные действия. Один участник вправе инициировать проверку, другой — подтвердить показатели, третий — подписать документ в пределах своей компетенции. При недостаточности полномочий требуется формальное обращение к уполномоченному органу; последующая подпись не всегда устраняет последствия преждевременно исполненной операции.\n\nПроверка исходных данных. Для решения следует сопоставить первоначальную справку с подтверждающими материалами, установить расчётный период, получателя средств, правовое основание и ответственного за исполнение. В описанном случае предмет проверки касается запрашиваемых бюджетных расходов и межбюджетного финансирования. Если используются прогнозные показатели, они должны сохранять статус прогноза до появления надлежащего подтверждения. При возвратных операциях отдельно учитываются сумма основного обязательства, проценты и срок платежа; при трансфертах — форма, целевое назначение и условия софинансирования.\n\nРесурсные и временные ограничения. Финансовый орган не может считать будущие средства уже доступными, а ведомство-инициатор не должно обещать результат, выполнение которого зависит от неподтверждённых решений других участников. Полная повторная экспертиза может защитить от ошибки в расчётах, но при этом затянуть решение обозначенной проблемы. Срочное финансирование, напротив, способно временно улучшить показатель, однако без проверки процедуры оставит риск возврата средств или невозможности исполнения. Важно выбрать последовательность мероприятий, для которой можно установить проверяемые контрольные точки.\n\nИнтересы и публичная отчётность. Для получателей услуги и жителей важна предсказуемость сроков; для профильной организации — непрерывность деятельности; для контрольного органа — прозрачность оснований; для бюджетной команды — сопоставимость показателей по всем уровням финансового плана. Некоторые профессионально сформулированные способы действий будут юридически допустимыми только после дополнительных условий, хотя в текущей ситуации уступят другому варианту по срокам или ресурсам. Прежде чем проголосовать, определите, какой из пяти вариантов сразу запускает наиболее обоснованную цепочку действий, не подменяя решение обещанием последующего оформления. Письменное обоснование не требуется.","decision_options":["Уточнить загрузку склада и проверить транспортную схему","Учесть действующих производителей и подготовить заявку по объёму потерь","Предусмотреть поэтапную региональную поддержку только по бесспорно подтверждённой части потребности и отдельно продолжить федеральное согласование","Разделить расходы между краткосрочным мероприятием и инвестиционной программой, утвердив окончательный объём после повторного отраслевого расчёта","Согласовать предварительное распределение на основании проекта региональной заявки, предполагая последующее оформление федерального источника"],"effect_plan":{"options":[{"key":"option_1","news":"Подготовка итогового решения перенесена до дополнительной сверки.","trust":0,"lawful":true,"description":"Выбран дополнительный контрольный этап. Его проведение допустимо, но отодвигает решение основной задачи, описанной в обстоятельствах события.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.01,"enterprises":6},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false},{"key":"option_2","news":"Складская сеть для местных производителей — Заявка подготовлена","trust":2,"lawful":true,"description":"В базе отражены десять уже работающих производителей и текущие потери продукции. Заявка подготовлена; будущая экономия от склада пока не увеличивает доходы.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"activity":-0.004,"enterprises":10},"public_interest":"beneficial","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":true},{"key":"option_3","news":"Региональные и федеральные меры разделены, результат остаётся неполным.","trust":0,"lawful":true,"description":"Частичный способ финансирования может быть законным при самостоятельном подтверждении лимитов, однако не обеспечивает комплексного решения в рамках текущей заявки.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.01,"enterprises":6},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false},{"key":"option_4","news":"Исполнение разделено на этапы, вопрос сроков остался открытым.","trust":-1,"lawful":true,"description":"Поэтапное изменение возможно в установленной процедуре, но выбранная последовательность не отвечает основному срочному ограничению и требует отдельного решения.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы обосновываются, включаются в проект бюджета и проходят установленный в игре маршрут ФЗ. Вариант размечен автором как допустимый в учебной процедуре; это не заключение о действующих нормах права. Подготовка заявки не перечисляет средства.","fiscal_effect":{"cost":0.002,"activity":-0.01,"enterprises":6},"public_interest":"neutral","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false},{"key":"option_5","news":"Контролёры обнаружили несоответствие последовательности финансовых решений.","trust":-2,"lawful":false,"description":"Предварительная договорённость не заменяет документального основания бюджетного обязательства. Последующее оформление не устраняет исходную процедурную ошибку.","legal_basis":"Правила деловой игры, этап 13.1.4–13.6: расходы и результаты должны опираться на подтверждённые расчёты. Фиктивный учёт средств, работ или результатов нарушает учебную процедуру. Вариант размечен автором как недопустимый в игре; это не заключение о действующих нормах права.","fiscal_effect":{"cost":0.005,"activity":-0.018,"enterprises":4},"public_interest":"harmful","authorized_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"protects_role_interest":false}]},"allowed_roles":["министр финансов","председатель правительства","губернатор","глава региона","министр экономики"],"comic_scene":{"scene_id":"scene-budget-region-2026-47-food-logistics","case_key":"budget-region-2026-47-food-logistics","title":"Складская сеть для местных производителей","category":"Региональные финансы","format":"animated-svg","version":1,"alt":"Авторская сцена к ситуации «Складская сеть для местных производителей»","media_label":"Региональный финансовый обзор","news_lead":"Бюджетная комиссия обсуждает ситуацию «Складская сеть для местных производителей»."},"source_note":"Авторская учебная ситуация GOS//SIMS, не сообщение о реальном происшествии. Все суммы, сметы, исходные показатели и последствия являются параметрами игры, а не официальной статистикой. География 